/* One A4 landscape page (the sizes below are CSS px at 96 per inch: 1122 x 793).
   Every rule is scoped under .certificate-container: Frappe's own print stylesheet sets margins
   on `.print-format p` and `.print-format h1`, which a bare class would lose to. */
.print-format {
    /* The page is given as exact dimensions (A4 landscape), not as orientation plus a size: Frappe's
       Chrome path injects its own @page size from the portrait paper size, which wins over both
       `orientation: Landscape` and an @page rule here. */
    page-width: 297mm;
    page-height: 210mm;
    margin-top: 0;
    margin-bottom: 0;
    margin-left: 0;
    margin-right: 0;
}

@page {
    size: A4 landscape;
    margin: 0;
}

.certificate-container {
    position: relative;
    display: flex;
    width: 1122px;
    height: 793px;
    box-sizing: border-box;
    overflow: hidden;
    background: #ffffff;
    color: #3c210e;
    font-family: "Archivo", system-ui, sans-serif;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

.certificate-container .certificate-frame {
    position: absolute;
    display: block;
    pointer-events: none;
}

.certificate-container .certificate-frame-outer {
    inset: 28px;
    border: 3px solid #f8c4b7;
    border-radius: 22px;
}

.certificate-container .certificate-frame-inner {
    inset: 42px;
    border: 1px solid rgba(60, 33, 14, 0.28);
    border-radius: 12px;
}

.certificate-container .certificate-content {
    position: absolute;
    inset: 0;
    box-sizing: border-box;
    padding: 66px 120px 62px;
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
}

.certificate-container .certificate-logo {
    display: block;
    width: 250px;
    height: auto;
}

.certificate-container .certificate-title {
    margin: 30px 0 0;
    font-size: 54px;
    font-weight: 500;
    letter-spacing: -0.01em;
    line-height: 1.05;
}

.certificate-container .certificate-rule {
    display: block;
    width: 56px;
    height: 4px;
    margin-top: 22px;
    border-radius: 999px;
    background: #f8c4b7;
}

.certificate-container .certificate-lead {
    margin: 24px 0 0;
    font-size: 19px;
    line-height: 1.3;
    color: #665f59;
}

.certificate-container .certificate-lead-course {
    margin-top: 16px;
}

.certificate-container .certificate-recipient {
    margin: 8px 0 0;
    padding: 0 16px;
    font-size: 50px;
    font-weight: 500;
    line-height: 1.15;
    background: linear-gradient(transparent 62%, #f8c4b7 62%);
}

.certificate-container .certificate-course {
    margin: 6px 0 0;
    max-width: 760px;
    font-size: 30px;
    font-weight: 500;
    line-height: 1.2;
}

.certificate-container .certificate-assessments {
    margin: 6px 0 0;
    font-size: 16px;
    line-height: 1.3;
    color: #665f59;
}

.certificate-container .certificate-details {
    display: flex;
    justify-content: center;
    margin: 28px 0 0;
    padding: 0;
}

.certificate-container .certificate-detail {
    display: flex;
    flex-direction: column-reverse;
    align-items: center;
    gap: 6px;
    padding: 4px 36px;
    border-left: 1px solid rgba(60, 33, 14, 0.25);
}

.certificate-container .certificate-detail:first-child {
    border-left: 0;
}

.certificate-container .certificate-detail dt {
    margin: 0;
    font-size: 13px;
    font-weight: 500;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: #665f59;
}

.certificate-container .certificate-detail dd {
    margin: 0;
    font-size: 34px;
    font-weight: 400;
    line-height: 1.1;
}

.certificate-container .certificate-signatories {
    margin-top: auto;
    width: 100%;
    display: grid;
    grid-template-columns: 1fr auto 1fr;
    align-items: end;
    gap: 24px;
}

.certificate-container .certificate-signatory {
    display: flex;
    flex-direction: column;
    width: 260px;
}

.certificate-container .certificate-signatory-left {
    justify-self: start;
    text-align: left;
}

.certificate-container .certificate-signatory-right {
    justify-self: end;
    text-align: left;
}

/* Room above the line for a signature image later. */
.certificate-container .certificate-signature-space {
    display: block;
    height: 40px;
    width: 100%;
}

.certificate-container .certificate-signature-line {
    border-bottom: 1.5px solid #3c210e;
}

.certificate-container .certificate-seal {
    position: relative;
    display: block;
    width: 104px;
    height: 104px;
}

.certificate-container .certificate-seal-ring {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
}

.certificate-container .certificate-bird {
    position: absolute;
    left: 24px;
    top: 28px;
    width: 56px;
    height: auto;
}

.certificate-container .certificate-role {
    margin: 4px 0 0;
    font-size: 13px;
    font-weight: 500;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: #665f59;
}

.certificate-container .certificate-people {
    margin: 10px 0 0;
    font-size: 19px;
    line-height: 1.35;
}

.certificate-container .certificate-people strong {
    font-weight: 500;
}
